import {find,isLocked,clone} from '../document/model.js';
import {escape} from '../renderer/svg.js';
import {hasLayerAnimation,motionBlurSettings,MOTION_BLUR_SAMPLE_COUNTS} from '../animation/motion-blur.js';
const sessions=new WeakMap();
export function validMotionBlurValue(prop,value){return prop==='enabled'?typeof value==='boolean':prop==='shutterAngle'?Number.isFinite(value)&&value>=0&&value<=360:prop==='samples'&&MOTION_BLUR_SAMPLE_COUNTS.includes(value);}
export class MotionBlurPreviewSession{
 constructor(a,id){this.a=a;this.id=id;this.closed=false;this.dirty=false;this.values=motionBlurSettings(find(a.doc,id)||{});this.baseline=clone(this.values);a.appearancePreview??=new Map();}
 set(prop,value){if(this.closed||!find(this.a.doc,this.id)||isLocked(this.a.doc,this.id)||!validMotionBlurValue(prop,value))return false;this.values[prop]=value;if(prop!=='enabled')this.values.enabled=true;this.dirty=JSON.stringify(this.values)!==JSON.stringify(this.baseline);this.a.appearancePreview.set(this.id,{...this.a.appearancePreview.get(this.id),motionBlur:clone(this.values)});return true;}
 refresh(){if(this.closed)return;if(!find(this.a.doc,this.id)){this.cancel();return;}if(!this.dirty){this.values=motionBlurSettings(find(this.a.doc,this.id));this.baseline=clone(this.values);if(this.a.appearancePreview.get(this.id)?.motionBlur)this.a.appearancePreview.set(this.id,{...this.a.appearancePreview.get(this.id),motionBlur:clone(this.values)});}}
 finish(){const remaining={...this.a.appearancePreview.get(this.id)};delete remaining.motionBlur;if(Object.keys(remaining).length)this.a.appearancePreview.set(this.id,remaining);else this.a.appearancePreview.delete(this.id);this.closed=true;}
 cancel(){if(this.closed)return;this.finish();this.a.renderStage();}
 apply(){if(this.closed)return false;const n=find(this.a.doc,this.id);if(!n||isLocked(this.a.doc,this.id)){this.cancel();return false;}const values=clone(this.values);this.finish();if(this.dirty)this.a.mutate('Motion blur',()=>n.motionBlur=values);else this.a.renderStage();return true;}
}
export function refreshMotionBlurEditor(a){const entry=sessions.get(a);if(!entry)return;entry.session.refresh();if(entry.session.closed){entry.dialog.close();return;}entry.sync();}
export function showMotionBlur(a,id=a.selected[0]){
 const n=find(a.doc,id);if(!n)return a.toast('Select a layer first.');const previous=sessions.get(a);previous?.session.cancel();previous?.dialog.close();a.properties?.flush();a.selected=[id];a.render();
 const session=new MotionBlurPreviewSession(a,id),locked=isLocked(a.doc,id),d=document.createElement('dialog');d.id='motion-blur-editor';d.className='motion-blur-editor';d.dataset.modal='false';d.setAttribute('aria-labelledby','motion-blur-editor-title');
 const qualities={3:'Fast preview',5:'Light',7:'Balanced',9:'Smooth',11:'Highest quality'};
 d.innerHTML=`<header><strong id="motion-blur-editor-title">Motion blur · ${escape(n.name)}</strong><button data-blur-cancel aria-label="Close motion blur editor">×</button></header><fieldset ${locked?'disabled':''}><label class="motion-blur-switch"><input data-blur-enabled type="checkbox"> Preview motion blur</label><label class="motion-blur-angle"><span>Shutter angle (degrees)</span><input data-blur-number type="number" min="0" max="360" step="1" aria-label="Shutter angle in degrees"><input data-blur-angle type="range" min="0" max="360" step="1" aria-label="Shutter angle slider"></label><label class="motion-blur-quality">Quality<select data-blur-samples>${MOTION_BLUR_SAMPLE_COUNTS.map(count=>`<option value="${count}">${count} samples · ${qualities[count]}</option>`).join('')}</select></label><p class="motion-blur-help">0° keeps motion sharp; 180° gives a natural trail. Higher quality takes more time. Adjusting a control turns Preview on.</p><output class="motion-blur-status"></output><footer><button data-blur-cancel>Cancel</button><button data-blur-apply class="primary">Apply</button></footer></fieldset>${locked?'<p class="motion-blur-help">Unlock this layer to change its motion blur.</p>':''}`;
 document.body.append(d);let scheduled=0;const preview=()=>{if(scheduled)return;scheduled=requestAnimationFrame(()=>{scheduled=0;if(!session.closed)a.renderStage();});};
 const sync=()=>{const values=session.values;d.querySelector('[data-blur-enabled]').checked=values.enabled;for(const selector of ['[data-blur-number]','[data-blur-angle]']){const input=d.querySelector(selector);if(document.activeElement!==input)input.value=values.shutterAngle;}d.querySelector('[data-blur-samples]').value=values.samples;const layer=find(a.doc,id);d.querySelector('.motion-blur-status').textContent=(values.enabled?'Preview on':'Preview off')+' · Frame '+Math.round(a.time*a.doc.fps)+(layer&&hasLayerAnimation(layer)?' · Play to see the motion trail':' · Animate this layer to see a trail');};
 d.addEventListener('input',e=>{const input=e.target;let prop,value;if(input.hasAttribute('data-blur-enabled')){prop='enabled';value=input.checked;}else if(input.hasAttribute('data-blur-number')||input.hasAttribute('data-blur-angle')){prop='shutterAngle';value=Number(input.value);}else if(input.hasAttribute('data-blur-samples')){prop='samples';value=Number(input.value);}if(prop&&session.set(prop,value)){sync();preview();}});
 d.querySelector('[data-blur-samples]').addEventListener('change',e=>{if(session.set('samples',Number(e.target.value))){sync();preview();}});
 d.querySelector('[data-blur-apply]').onclick=()=>a.safe(()=>{const number=d.querySelector('[data-blur-number]');if(!number.checkValidity()){number.reportValidity();return;}if(scheduled){cancelAnimationFrame(scheduled);scheduled=0;}if(session.apply())d.close();});d.querySelectorAll('[data-blur-cancel]').forEach(button=>button.onclick=()=>d.close());d.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();d.close();}});d.addEventListener('close',()=>{if(scheduled)cancelAnimationFrame(scheduled);session.cancel();if(sessions.get(a)?.dialog===d)sessions.delete(a);d.remove();},{once:true});sessions.set(a,{session,dialog:d,sync});sync();d.show();return d;
}
